const lessons=[
{title:'مقدمة في العتاد',sub:'تعريف المكونات المادية والتمييز بين المكونات الداخلية والأجهزة الطرفية.',body:'العتاد هو الأجزاء المادية الملموسة من نظام الحاسوب. تشمل المكونات الداخلية المعالج والذاكرة واللوحة الأم ووحدات التخزين ومزود الطاقة. أما الأجهزة الطرفية فتتصل بالحاسوب لتوفير الإدخال أو الإخراج أو الاتصال. هذا التقسيم يساعد على فهم وظيفة كل جزء وعلاقته ببقية النظام.'},
{title:'المعالجة: CPU وGPU',sub:'كيف تُنفّذ التعليمات وتُعالج الرسوم والبيانات.',body:'تقوم وحدة المعالجة المركزية بتنفيذ التعليمات العامة وإجراء العمليات الحسابية والمنطقية. أما وحدة معالجة الرسوميات فتركز على عمليات الرسوم والصور والمهام التي يمكن تنفيذها بالتوازي. قد تكون وحدة الرسوميات مدمجة أو موجودة على بطاقة منفصلة. لا يعني وجود بطاقة منفصلة أن كل مهمة ستصبح أسرع؛ يعتمد ذلك على طبيعة المهمة.'},
{title:'الذاكرة والتخزين',sub:'الفرق بين الذاكرة المؤقتة وحفظ الملفات بصورة دائمة.',body:'تحتفظ RAM بالبيانات التي يحتاج إليها النظام أثناء التشغيل، وهي ذاكرة متطايرة. أما SSD وHDD فيحفظان البيانات حتى بعد إيقاف الحاسوب. يستخدم SSD ذاكرة فلاش، بينما يعتمد HDD على أطباق مغناطيسية وأجزاء ميكانيكية. عند المقارنة، انتبه إلى السعة والسرعة والواجهة والتكلفة.'},
{title:'اللوحة الأم والتوصيلات',sub:'كيف ترتبط مكونات الحاسوب ببعضها.',body:'تجمع اللوحة الأم عدداً من المقابس والشقوق والمنافذ التي تسمح بتركيب المكونات وتبادل البيانات والطاقة. يجب التأكد من توافق مقبس المعالج ونوع الذاكرة وحجم اللوحة والمنافذ قبل اختيار القطع. وجود منفذ متشابه شكلاً لا يضمن وحده توافق كل الأجهزة.'},
{title:'الطاقة والتبريد',sub:'دور مزود الطاقة في تشغيل الحاسوب وأهمية إدارة الحرارة.',body:'يوفر مزود الطاقة الجهود الكهربائية المناسبة لمكونات الحاسوب. ينبغي أن تكون قدرته وموصلاته مناسبة لتكوين الجهاز. تنتج المكونات حرارة أثناء التشغيل؛ لذلك تُستخدم المشتتات والمراوح أو حلول تبريد أخرى لنقل الحرارة والمحافظة على ظروف تشغيل مناسبة.'},
{title:'أجهزة الإدخال والإخراج',sub:'أمثلة على الأجهزة التي تسمح للمستخدم بإدخال البيانات واستقبال النتائج.',body:'تُستخدم لوحة المفاتيح والفأرة والميكروفون وأجهزة المسح لإدخال البيانات. وتعرض الشاشة المعلومات، بينما تقدم السماعات الصوت وتنتج الطابعة نسخاً ورقية. بعض الأجهزة تجمع أكثر من وظيفة. وتساعد التقنيات التكيفية، مثل أجهزة تتبع العين أو وسائل الإدخال البديلة، أشخاصاً على استخدام الحاسوب بطرق تناسب احتياجاتهم.'},
{title:'أجهزة الاتصال المادية',sub:'بطاقات الشبكة والكابلات والراوتر والسويتش.',body:'تتيح بطاقة الشبكة اتصال الحاسوب بالشبكة السلكية أو اللاسلكية. تنقل كابلات Ethernet البيانات عبر اتصال سلكي، بينما يستخدم محول Wi‑Fi الاتصال اللاسلكي. يربط السويتش أجهزة ضمن شبكة محلية، ويقوم الراوتر بتوجيه البيانات بين شبكات مختلفة. الأجهزة هي عتاد، أما قواعد نقل البيانات فهي بروتوكولات وليست قطعاً مادية.'},
{title:'اختيار القطع والتوافق',sub:'خطوات أولية لتجميع حاسوب متوافق.',body:'ابدأ بتحديد الاستخدام المطلوب، ثم اختر المعالج واللوحة الأم والذاكرة والتخزين وبطاقة الرسوميات عند الحاجة. تحقق من توافق المقبس ونوع الذاكرة وحجم الصندوق وطول البطاقة وموصلات الطاقة. قارن احتياجات الطاقة بالتقدير الإجمالي للاستهلاك، ولا تعتمد على الاسم التجاري أو الشكل وحده للحكم على التوافق.'}
 ];
const lessonSlidesData = lessons.flatMap((lesson, lessonIndex) => {
 const sentences=(lesson.body||'').split(/(?<=[.!؟])\s+/).filter(Boolean);
 const first=Math.max(1,Math.ceil(sentences.length/3));
 const chunks=[sentences.slice(0,first),sentences.slice(first,first*2),sentences.slice(first*2)];
 const labels=['الفكرة الأساسية','شرح مبسط','مثال وتطبيق'];
 return chunks.map((chunk,partIndex)=>({title:lesson.title,sub:lesson.sub,section:labels[partIndex],body:chunk.length?chunk.join(' '):lesson.sub,lessonIndex,partIndex}));
});
