function geminiRequestError(data,status){return data?.code==='INVALID_API_KEY'?quizAIText('invalidKey'):data?.error||`Gemini request failed (HTTP ${status}).`}
function setQuizAIStatus(message,details=''){$('quizAIStatus').textContent=message+details}
function isValidCustomQuizQuestion(q){return q&&typeof q==='object'&&typeof q.q==='string'&&q.q.trim().length>0&&q.q.length<=500&&Array.isArray(q.a)&&q.a.length===4&&q.a.every(answer=>typeof answer==='string'&&answer.trim().length>0&&answer.length<=200)&&new Set(q.a.map(answer=>answer.trim().toLowerCase())).size===4&&Number.isInteger(q.c)&&q.c>=0&&q.c<4&&typeof q.why==='string'&&q.why.trim().length>0&&q.why.length<=500&&['سهل','متوسط','متقدم'].includes(q.level)&&q.type==='general'}
function loadCustomQuizQuestions(){try{const stored=localStorage.getItem(customQuizStorageKey);if(!stored)return;const parsed=JSON.parse(stored);if(!Array.isArray(parsed)||!parsed.every(isValidCustomQuizQuestion))throw new Error('Saved question data is invalid.');customQuizQuestions=parsed;questions.push(...customQuizQuestions)}catch(error){customQuizLoadError=error instanceof Error?error.message:String(error);setQuizAIStatus(quizAIText('loadFailed'),customQuizLoadError)}}
function parseGeneratedQuestions(text,level){
 const content=text.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');
 const first=content.indexOf('['),last=content.lastIndexOf(']');
 if(first<0||last<first)throw new Error('لم تُرجع الخدمة قائمة أسئلة بصيغة JSON.');
 const parsed=JSON.parse(content.slice(first,last+1));
 if(!Array.isArray(parsed)||parsed.length!==5)throw new Error('يجب أن تحتوي النتيجة على خمسة أسئلة بالضبط.');
 const normalized=parsed.map(q=>({...q,level,type:'general'}));
 if(!normalized.every(isValidCustomQuizQuestion)||new Set(normalized.map(q=>q.q.trim().toLowerCase())).size!==5)throw new Error('أحد الأسئلة غير صالح أو توجد أسئلة مكررة.');
 return normalized;
}
function updateQuizAIControls(){
 $('quizAIHeading').textContent=quizAIText('heading');
 $('quizLevelLabel').textContent=quizAIText('level');
 $('quizGenerate').textContent=quizAIText('generate');
 $('quizAIStart').textContent=quizAIText('start');
 $('quizLevel').options[0].textContent=quizAIText('easy');
 $('quizLevel').options[1].textContent=quizAIText('medium');
 $('quizLevel').options[2].textContent=quizAIText('hard');
 if(customQuizLoadError)setQuizAIStatus(quizAIText('loadFailed'),customQuizLoadError);
}
async function generateCustomQuiz(){
 const level=$('quizLevel').value,button=$('quizGenerate');
 button.disabled=true;$('quizAIStart').hidden=true;
 setQuizAIStatus(quizAIText('generating'));
 try{
  if(location.protocol==='file:')throw new Error(quizAIText('setup'));
  const prompt=`Create exactly five multiple-choice questions about physical computer hardware only. Do not ask about software, networking, internet, or protocols. Write every question, all four answer choices, and each explanation in Arabic. Return only a JSON array of objects shaped exactly like {"q":"question","a":["choice 1","choice 2","choice 3","choice 4"],"c":0,"why":"short explanation"}. "c" is the zero-based index of the single correct answer. Questions must be factually accurate, distinct, and suitable for the selected difficulty (${level}).`;
  const response=await fetch('/api/gemini',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt,apiKey:sessionStorage.getItem('hh-gemini-key')||''})});
  const responseText=await response.text();
  let data;
  try{data=JSON.parse(responseText)}catch(error){throw new Error(response.ok?'استجابة الخادم ليست JSON صالحاً. حاول مرة أخرى.':`${quizAIText('setup')} (HTTP ${response.status})`)}
  if(!response.ok)throw new Error(geminiRequestError(data,response.status));
  if(typeof data.text!=='string'||!data.text.trim())throw new Error('أعاد Gemini إجابة فارغة. حاول مرة أخرى.');
  const generated=parseGeneratedQuestions(data.text,level),updated=[...customQuizQuestions,...generated];
  localStorage.setItem(customQuizStorageKey,JSON.stringify(updated));
  customQuizQuestions=updated;lastGeneratedQuizQuestions=generated;questions.push(...generated);
  customQuizLoadError='';setQuizAIStatus(quizAIText('added')+quizAIText(level==='سهل'?'easy':level==='متوسط'?'medium':'hard')+'.');
  $('quizAIStart').hidden=false;
 }catch(error){
  setQuizAIStatus(quizAIText('failed'),error instanceof TypeError?quizAIText('setup'):error instanceof Error?error.message:String(error));
 }finally{button.disabled=false}
}
loadCustomQuizQuestions();
$('quizGenerate').addEventListener('click',generateCustomQuiz);
$('quizAIStart').addEventListener('click',()=>startQuiz(activeLevel,'general',lastGeneratedQuizQuestions));
let pageTransitionId=0,pageTransitionAnimation=null,transitioningPage=null;
async function navigate(page){
 const nextPage=$('page-'+page);
 if(!nextPage)return;
 const currentPage=document.querySelector('.page.active');
 if(currentPage===nextPage&&!pageTransitionAnimation)return;
 if(transitioningPage===nextPage)return;

 const transitionId=++pageTransitionId;
 pageTransitionAnimation?.cancel();
 pageTransitionAnimation=null;
 transitioningPage=nextPage;
 const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 const slideDirection=document.documentElement.dir==='rtl'?-1:1;

 if(currentPage&&currentPage!==nextPage&&!reducedMotion&&typeof currentPage.animate==='function'){
  const exitAnimation=currentPage.animate(
   [{opacity:1,transform:'translateX(0)'},{opacity:0,transform:`translateX(${slideDirection*18}px)`}],
   {duration:190,easing:'cubic-bezier(.4,0,.2,1)',fill:'both'}
  );
  pageTransitionAnimation=exitAnimation;
  try{await pageTransitionAnimation.finished}catch{}
  if(transitionId!==pageTransitionId)return;
 }

 document.querySelectorAll('.page').forEach(element=>element.classList.toggle('active',element===nextPage));
 if(pageTransitionAnimation){pageTransitionAnimation.cancel();pageTransitionAnimation=null}
 document.querySelectorAll('#nav button').forEach(button=>button.classList.toggle('active',button.dataset.page===page));
 const lang=localStorage.getItem('hh-language')||'ar',t=uiText[lang]||uiText.en,names={home:t.home,lab:t.lab,lessons:t.lessons,library:t.library,quiz:t.quiz,ai:t.ai,games:t.games};
 $('crumb').textContent='HardHub / '+(names[page]||t.home);
 if(page==='lab')resizeLab();
 if(page==='home')resizeHero();
 if(page==='games'){
  const activeFrame=Object.values(gameFrames).find(frame=>!frame.classList.contains('games-frame-hidden'));
  if(activeFrame)resizeGamesFrame(activeFrame);
 }
 window.scrollTo({top:0,behavior:'auto'});

 if(!reducedMotion&&typeof nextPage.animate==='function'){
  pageTransitionAnimation=nextPage.animate(
   [{opacity:0,transform:`translateX(${-slideDirection*18}px)`},{opacity:1,transform:'translateX(0)'}],
   {duration:260,easing:'cubic-bezier(.2,.7,.2,1)'}
  );
  try{await pageTransitionAnimation.finished}catch{}
  if(transitionId!==pageTransitionId)return;
 }
 pageTransitionAnimation=null;
 transitioningPage=null;
}
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.page)));document.querySelectorAll('[data-goto]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.goto)));
function resizeGamesFrame(frame){if(frame.contentWindow.resizeThreeCanvas)frame.contentWindow.resizeThreeCanvas()}
