const lessonEN=[
{title:'Introduction to Hardware',sub:'Define physical components and distinguish internal components from peripherals.',body:'Hardware means the tangible physical parts of a computer system. Internal components include the CPU, memory, motherboard, storage drives, and power supply. Peripherals connect to the computer to provide input, output, or connectivity. This classification helps explain each component and its relationship to the system.'},
{title:'Processing: CPU and GPU',sub:'How instructions are executed and graphics and data are processed.',body:'The CPU executes general instructions and arithmetic or logical operations. The GPU focuses on graphics, images, and tasks that can be processed in parallel. Graphics may be integrated or provided by a separate card. A dedicated card does not make every task faster; the result depends on the workload.'},
{title:'Memory and Storage',sub:'Understand the difference between temporary memory and persistent file storage.',body:'RAM holds data the system needs while running and is volatile. SSDs and HDDs retain data after the computer is turned off. An SSD uses flash memory, while an HDD uses magnetic platters and mechanical parts. Compare capacity, speed, interface, and cost.'},
{title:'Motherboard and Connections',sub:'How computer components connect to one another.',body:'The motherboard provides sockets, slots, and ports that allow components to be installed and exchange data and power. Check CPU socket, memory type, board size, and ports before selecting parts. A connector that looks similar does not guarantee compatibility.'},
{title:'Power and Cooling',sub:'The role of the power supply and the importance of thermal management.',body:'The power supply provides suitable voltages to computer components. Its capacity and connectors must match the system configuration. Components generate heat while running, so heatsinks, fans, or other cooling solutions move heat away and maintain suitable operating conditions.'},
{title:'Input and Output Devices',sub:'Examples of devices used to enter data and receive results.',body:'Keyboards, mice, microphones, and scanners provide input. Monitors display information, speakers provide sound, and printers produce paper copies. Some devices combine functions. Adaptive technologies such as eye tracking and alternative input devices can help people use computers in ways that suit their needs.'},
{title:'Physical Networking Devices',sub:'Network adapters, cables, routers, and switches.',body:'A network adapter connects a computer to a wired or wireless network. Ethernet cables carry data over a wired connection, while Wi-Fi adapters use wireless connections. A switch connects devices within a local network, and a router routes data between different networks. Devices are hardware; data-transfer rules are protocols.'},
{title:'Choosing Compatible Components',sub:'Basic steps for selecting compatible computer parts.',body:'Start by identifying the intended use, then choose a CPU, motherboard, memory, storage, and graphics card if needed. Check socket, memory type, case size, card length, and power connectors. Compare power needs with the estimated total load; brand or appearance alone does not determine compatibility.'}
];
function isEnglish(){return (localStorage.getItem('hh-language')||'ar')!=='ar'}
function localPart(p){return isEnglish()&&partEN[p.id]?{...p,...partEN[p.id]}:p}
function localLesson(l){const en=localStorage.getItem('hh-language')!=='ar';return en?{...l,...(lessonEN[l.lessonIndex]||{})}:l}
function partCard(p){p=localPart(p);return `<article class="part-card" data-part="${p.id}"><span class="part-tag">${p.cat}</span><h3>${p.name}</h3><p>${p.desc}</p><div class="open">${isEnglish()?'View details →':'عرض التفاصيل ←'}</div></article>`}
function renderPartCards(){const basics=parts.slice(0,6);$('homeParts').innerHTML=basics.map(partCard).join('');$('libraryParts').innerHTML=parts.map(partCard).join('');document.querySelectorAll('[data-part]').forEach(el=>el.addEventListener('click',()=>{builderMode=false;selectPart(el.dataset.part);navigate('lab');updateBuilderLabels()}));}
let slideIndex=0;
function renderLessons(){const saved=Number(localStorage.getItem('hh-slide')||0);slideIndex=Math.max(0,Math.min(saved,lessonSlidesData.length-1));renderSlide();updateProgress();}
function renderSlide(){const l=lessonSlidesData[slideIndex],en=isEnglish(),tr=en?lessonEN[l.lessonIndex]:null;const labels=en?['Core idea','Simple explanation','Example and application']:['الفكرة الأساسية','شرح مبسط','مثال وتطبيق'];let body=l.body;if(tr){const sentences=tr.body.split(/(?<=[.!?])\s+/).filter(Boolean);const chunks=[sentences.slice(0,2),sentences.slice(2,4),sentences.slice(4)];body=chunks[l.partIndex]?.join(' ')||tr.body;}$('lessonSlides').innerHTML=`<div class="slide-top"><span>HARDHUB LEARNING SLIDES · ${en?'LESSON':'المحور'} ${l.lessonIndex+1}</span><span class="slide-count">${en?'Slide':'الشريحة'} ${slideIndex+1} ${en?'of':'من'} ${lessonSlidesData.length}</span></div><div class="slide-lesson-label">${en?'Topic':'المحور'} ${l.lessonIndex+1} · ${tr?tr.title:l.title}</div><h2>${tr?tr.title:l.title}</h2><p>${tr?tr.sub:l.sub}</p><div class="slide-highlight">${body}</div><p class="slide-tip">${en?'Use this as a study summary and compare it with your course book.':'ملاحظة: راجع هذا الشرح مع صفحات الكتاب المقرر للتأكد من مطابقة التفاصيل.'}</p>`;$('lessonControls').innerHTML=`<button class="btn" id="slidePrev" ${slideIndex===0?'disabled':''}>${en?'Previous':'السابق'}</button><div class="slide-dots">${lessonSlidesData.map((_,i)=>`<button class="slide-dot ${i===slideIndex?'active':''}" aria-label="Slide ${i+1}" data-slide="${i}"></button>`).join('')}</div><button class="btn primary" id="slideNext">${slideIndex===lessonSlidesData.length-1?(en?'Back to start':'العودة للبداية'):(en?'Next slide':'الشريحة التالية')}</button>`;$('slidePrev').onclick=()=>goSlide(slideIndex-1);$('slideNext').onclick=()=>goSlide(slideIndex===lessonSlidesData.length-1?0:slideIndex+1);document.querySelectorAll('[data-slide]').forEach(b=>b.onclick=()=>goSlide(Number(b.dataset.slide)));}
function goSlide(i){slideIndex=(i+lessonSlidesData.length)%lessonSlidesData.length;localStorage.setItem('hh-slide',String(slideIndex));localStorage.setItem('hh-lesson-'+lessonSlidesData[slideIndex].lessonIndex,'1');renderSlide();updateProgress();}
function updateProgress(){let n=lessons.filter((_,i)=>localStorage.getItem('hh-lesson-'+i)==='1').length;$('progressStat').textContent=Math.round(n/lessons.length*100)+'%';}
function renderPicker(){ $('partPicker').innerHTML=parts.map(p=>{const x=localPart(p);return `<button data-pick="${p.id}" class="${p.id===selected?'active':''}">${x.name}</button>`}).join('');document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{builderMode=false;selectPart(b.dataset.pick);updateBuilderLabels()});}
function selectPart(id){selected=id;const base=parts.find(x=>x.id===id)||parts[0],p=localPart(base),en=isEnglish();$('partDetails').innerHTML=`<span class="eyebrow">${p.cat}</span><h2>${p.name}</h2><div class="en">${base.en}</div><p>${p.desc}</p><div class="spec-list"><div class="spec"><span>${en?'Function':'الوظيفة'}</span><span>${p.use}</span></div><div class="spec"><span>${en?'Connection':'الاتصال'}</span><span>${p.connect}</span></div><div class="spec"><span>${en?'Key fact':'معلومة مهمة'}</span><span>${p.detail}</span></div></div><button class="btn primary" id="relatedLesson">${en?'Read related lesson':'اقرأ الدرس المرتبط'}</button>`;$('relatedLesson').onclick=()=>{const map={cpu:1,gpu:1,ram:2,board:3,ssd:2,hdd:2,psu:4,cooler:4,monitor:5,keyboard:5,mouse:5,router:6};const idx=map[id]??0;const el=document.querySelector(`[data-lesson="${idx}"]`);navigate('lessons');el?.classList.add('expanded');el?.scrollIntoView({behavior:'smooth',block:'center'});};renderPicker();if(modelGroup){if(builderMode)refreshModel();else{while(modelGroup.children.length){const c=modelGroup.children[0];modelGroup.remove(c);disposeObject(c)}buildModel(modelGroup,p.kind);}}}
function disposeObject(obj){obj.traverse?.(o=>{o.geometry?.dispose?.();if(o.material){if(Array.isArray(o.material))o.material.forEach(m=>m.dispose());else o.material.dispose()}})}
const mat=(color,roughness=.55,metalness=.25)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
function box(group,x,y,z,sx,sy,sz,material,edge=false){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);group.add(m);if(edge){const e=new THREE.LineSegments(new THREE.EdgesGeometry(m.geometry),new THREE.LineBasicMaterial({color:0x64758a,transparent:true,opacity:.65}));e.position.copy(m.position);group.add(e)}return m}
function cylinder(group,x,y,z,r1,r2,h,material,rot=0){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,32),material);m.position.set(x,y,z);m.rotation.x=rot;group.add(m);return m}
function buildModel(group,kind){const dark=mat(0x263241,.42,.55),pcb=mat(0x1b594b,.65,.15),silver=mat(0x9ca8b6,.3,.7),gold=mat(0xd5ae62,.28,.65),black=mat(0x111820,.4,.35),blue=mat(0x4c8dff,.35,.35),fan=mat(0x68798c,.4,.35);if(kind==='cpu'){box(group,0,0,0,2.35,.28,2.35,dark,true);box(group,0,.19,0,1.55,.12,1.55,silver,true);box(group,0,.27,0,1.22,.045,1.22,gold,true);for(let i=-4;i<=4;i++){box(group,i*.22,-.19,1.2,.09,.08,.15,gold);box(group,i*.22,-.19,-1.2,.09,.08,.15,gold);box(group,1.2,-.19,i*.22,.15,.08,.09,gold);box(group,-1.2,-.19,i*.22,.15,.08,.09,gold)}}else if(kind==='gpu'){box(group,0,0,0,3.5,.42,1.35,dark,true);box(group,0,.25,0,3.25,.12,1.12,black);for(let x of [-.8,.8]){cylinder(group,x,.34,0,.43,.43,.12,fan,Math.PI/2);cylinder(group,x,.42,0,.1,.1,.08,silver,Math.PI/2);for(let j=0;j<6;j++){const a=j*Math.PI/3;box(group,x+Math.cos(a)*.22,.42,Math.sin(a)*.22,.32,.035,.09,blue).rotation.y=-a}}box(group,0,-.28,.62,2.7,.1,.08,gold)}else if(kind==='ram'){box(group,0,0,0,3.25,.17,.68,pcb,true);for(let i=0;i<8;i++){box(group,-1.3+i*.37,.14,0,.27,.18,.42,black,true);box(group,-1.3+i*.37,.24,0,.19,.035,.28,silver)}for(let i=0;i<16;i++)box(group,-1.48+i*.19,-.11,.02,.1,.035,.48,gold)}else if(kind==='board'){box(group,0,0,0,3.5,.16,3.1,pcb,true);box(group,-.45,.12,.35,1.1,.12,1.1,black,true);box(group,-.45,.2,.35,.72,.07,.72,silver,true);for(let i=0;i<4;i++)box(group,.65+i*.22,.14,.25,.13,.1,1.15,black,true);for(let i=0;i<3;i++)box(group,-.6+i*.55,.13,-.95,.36,.08,.3,blue);for(let i=0;i<8;i++)box(group,-1.4+i*.35,.1,1.2,.16,.08,.13,gold)}else if(kind==='ssd'){box(group,0,0,0,2.8,.12,.72,pcb,true);for(let i=0;i<4;i++)box(group,-.75+i*.5,.1,0,.38,.1,.45,black,true);box(group,1.48,-.03,0,.25,.09,.4,gold)}else if(kind==='hdd'){box(group,0,0,0,2.6,.55,2.1,silver,true);box(group,0,.29,0,2.35,.08,1.85,black);cylinder(group,-.15,.38,0,.72,.72,.06,silver,Math.PI/2);cylinder(group,-.15,.43,0,.16,.16,.08,gold,Math.PI/2);box(group,.75,.38,-.5,.12,.08,.85,silver)}else if(kind==='psu'){box(group,0,0,0,2.5,1.2,2,dark,true);box(group,0,.62,0,1.45,.04,1.45,black);for(let i=0;i<8;i++){const a=i*Math.PI/4;box(group,Math.cos(a)*.52,.68,Math.sin(a)*.52,.7,.025,.05,silver).rotation.y=-a}box(group,0,-.63,.7,1.15,.08,.1,gold)}else if(kind==='cooler'){box(group,0,-.25,0,1.8,.18,1.8,dark,true);for(let i=0;i<7;i++)box(group,0,-.05+i*.065,0,1.65,.035,1.65,silver);cylinder(group,0,.43,0,.72,.72,.16,black);cylinder(group,0,.53,0,.12,.12,.12,blue);for(let i=0;i<5;i++){const a=i*Math.PI*2/5;box(group,Math.cos(a)*.34,.53,Math.sin(a)*.34,.42,.045,.11,fan).rotation.y=-a}}else if(kind==='monitor'){box(group,0,.4,0,3.1,1.9,.15,black,true);box(group,0,.4,.09,2.85,1.65,.025,blue);box(group,0,-.8,0,.16,.65,.18,silver);box(group,0,-1.15,.1,1.2,.12,.65,dark)}else if(kind==='keyboard'){box(group,0,0,0,3.2,.16,1.15,dark,true);for(let r=0;r<4;r++)for(let c=0;c<13;c++)box(group,-1.42+c*.235,.11,-.38+r*.23,.18,.07,.16,silver);box(group,0,.11,.52,1.15,.07,.13,blue)}else if(kind==='mouse'){const m=new THREE.Mesh(new THREE.SphereGeometry(.72,32,20),dark);m.scale.set(.8,.48,1.15);m.position.y=.15;group.add(m);box(group,0,.39,-.18,.035,.05,.72,silver)}else if(kind==='router'){box(group,0,0,0,2.4,.45,1.2,dark,true);for(let i=0;i<4;i++){const a=new THREE.Mesh(new THREE.CylinderGeometry(.035,.035,1.35,12),black);a.position.set(-.8+i*.53,.82,-.4);a.rotation.z=-.12+i*.08;group.add(a)}for(let i=0;i<5;i++)box(group,-.7+i*.35,.28,.62,.1,.035,.08,blue)} }
