const apiInput=$('apiKeyInput');if(apiInput){apiInput.value=sessionStorage.getItem('hh-gemini-key')||'';$('apiKeyStatus').textContent=apiInput.value?'مفتاح محفوظ لهذه الجلسة.':'أدخل المفتاح هنا؛ سيُحفظ في جلسة المتصفح الحالية فقط.';$('saveApiKey').onclick=()=>{const key=apiInput.value.trim();if(!key){$('apiKeyStatus').textContent='ألصق المفتاح أولاً.';return}sessionStorage.setItem('hh-gemini-key',key);$('apiKeyStatus').textContent='تم حفظ المفتاح في هذه الجلسة. جرّب إرسال سؤال.'};$('clearApiKey').onclick=()=>{sessionStorage.removeItem('hh-gemini-key');apiInput.value='';$('apiKeyStatus').textContent='تم مسح المفتاح من جلسة المتصفح.'};}
